import { useTabs } from '@dreadnought/react/logic';
export function Example() {
  const { value, setValue } = useTabs({ defaultValue: 'first' });
  return <button onClick={() => setValue('second')} aria-pressed={value === 'second'}>Второй раздел</button>;
}

import { TabsAdapter } from '@dreadnought/react/unstyled';
export function Example() {
  return <TabsAdapter defaultValue="first"><TabsAdapter.List aria-label="Разделы"><TabsAdapter.Tab value="first">Первый</TabsAdapter.Tab><TabsAdapter.Tab value="second">Второй</TabsAdapter.Tab></TabsAdapter.List><TabsAdapter.Panel value="first">Первый раздел</TabsAdapter.Panel><TabsAdapter.Panel value="second">Второй раздел</TabsAdapter.Panel></TabsAdapter>;
}
